-- 3. เพิ่มหนังสือ (Books)
INSERT INTO public.books (id, title, english_title, author, translator, publisher, page_count, synopsis) VALUES
  ('11111111-0000-0000-0000-000000000001', 'The Silent Patient', 'แผนลวงคดีเงียบ', 'Alex Michaelides', 'อาสยา ฐกัดกุล', 'น้ำพุสำนักพิมพ์', 352, 'อลิเซีย จิตรกรสาวชื่อดังยิงสามีตัวเอง 5 นัดเข้าที่ใบหน้าแล้วนิ่งเงียบไม่ยอมพูดตลอด 6 ปี ธีโอ นักจิตบำบัดจึงขอเข้าไปรักษาเธอเพื่อไขปริศนา'),
  ('11111111-0000-0000-0000-000000000002', 'กลลวงซ่อนตาย', 'The Devotion of Suspect X', 'ฮิงาชิโนะ เคโงะ', 'วงษ์สิริ', 'ไดฟุกุ', 320, 'การดวลตรรกะคณิตศาสตร์อันไร้ช่องโหว่ระหว่างครูคณิตศาสตร์อัจฉริยะกับนักฟิสิกส์ เพื่อปกป้องผู้หญิงที่เขารัก'),
  ('11111111-0000-0000-0000-000000000003', 'Gone Girl', 'เล่นซ่อนหาย', 'Gillian Flynn', 'นพดล เวชสวัสดิ์', 'น้ำพุสำนักพิมพ์', 480, 'ภรรยาสาวหายตัวไปในวันครบรอบแต่งงาน ทิ้งเบาะแสที่บ่งชี้ว่าสามีคือฆาตกร แต่ความจริงกลับน่าสะพรึงกลัวยิ่งกว่า'),
  ('11111111-0000-0000-0000-000000000004', '1984 (หนึ่ง-เก้า-แปด-สี่)', 'Nineteen Eighty-Four', 'George Orwell', 'รัชชัย เรืองโชติวิทย์', 'สมมติ', 416, 'ในโลกเผด็จการเบ็ดเสร็จที่พี่เบิ้มสอดส่องประชาชนตลอดเวลา วินสตันพยายามกบฏด้วยการมีความคิดและความรัก'),
  ('11111111-0000-0000-0000-000000000005', 'เจ้าชายน้อย', 'The Little Prince', 'Antoine de Saint-Exupéry', 'อริยา ไพฑูรย์', 'อ่าน๑๐๑', 144, 'การเดินทางของเจ้าชายน้อยจากดาวบี 612 สู่ดาวโลก ที่เผยให้เห็นความหมายของความรักและมิตรภาพ'),
  ('11111111-0000-0000-0000-000000000006', 'หาญท้าชะตาฟ้า ปริศนายุทธจักร', 'Joy of Life (庆余年)', 'มาวนี่ (Mao Ni)', 'น.นพรัตน์', 'สยามอินเตอร์บุ๊คส์', 420, 'ฟ่านเสียน ชายหนุ่มผู้เกิดใหม่ในโลกยุทธภพพร้อมความทรงจำชาติก่อน ต้องก้าวเข้าสู่วังวนแห่งการแย่งชิงอำนาจและแผนการซ้อนแผน'),
  ('11111111-0000-0000-0000-000000000007', 'มังกรหยก', 'The Legend of the Condor Heroes', 'กิมย้ง (Jin Yong)', 'จำลอง พิศนาคะ', 'สร้างสรรค์บุ๊คส์', 600, 'มหากาพย์แห่งยุทธภพ การเติบโตของก๊วยเจ๋ง เด็กหนุ่มผู้ซื่อสัตย์กตัญญู กับอึ้งย้ง หญิงสาวผู้เปี่ยมไหวพริบ'),
  ('11111111-0000-0000-0000-000000000008', 'ข้างหลังภาพ', 'Behind the Painting', 'ศรีบูรพา (กุหลาบ สายประดิษฐ์)', NULL, 'ดอกหญ้า', 224, 'ความรักต่างวัยและต่างสถานะระหว่างหม่อมราชวงศ์กีรติกับนพพร ณ ดินแดนอาทิตย์อุทัย'),
  ('11111111-0000-0000-0000-000000000009', 'เพียงชั่วเวลากาแฟยังอุ่น', 'Before the Coffee Gets Cold', 'Toshikazu Kawaguchi', 'อภิญญา เตชะบุญเสริมสุข', 'แพรวสำนักพิมพ์', 248, 'ในร้านกาแฟโบราณ มีเก้าอี้พิเศษที่พาคนย้อนเวลากลับไปพบคนที่รักได้ก่อนที่กาแฟจะเย็นชืด'),
  ('11111111-0000-0000-0000-000000000010', '20th Century Boys', 'แก๊งนี้มีป่วน (20世紀少年)', 'Naoki Urasawa', NULL, 'เนชั่น เอ็ดดูเทนเมนท์', 220, 'เมื่อสมุดบันทึกคำทำนายที่กลุ่มเพื่อนเคยเขียนเล่นในวัยเด็ก เริ่มเกิดขึ้นจริงในโลกปัจจุบัน พร้อมลัทธิลึกลับ'),
  ('11111111-0000-0000-0000-000000000011', 'Monster (คนปีศาจ)', 'MONSTER', 'Naoki Urasawa', NULL, 'เนชั่น เอ็ดดูเทนเมนท์', 210, 'ศัลยแพทย์สมองตัดสินใจผ่าตัดช่วยชีวิตเด็กชายฝาแฝด โดยไม่รู้ว่าเด็กคนนั้นจะเติบโตขึ้นมาเป็นปีศาจเลือดเย็น');

-- 4. เพิ่มรีวิว (Reviews) (คะแนน rating เป็นทศนิยมทีละ 0.5 ตาม constraint 1.0 - 5.0)
INSERT INTO public.reviews (id, book_id, author_id, slug, title, summary, highlight_quote, tags, rating, status, published_at) VALUES
  ('22222222-0000-0000-0000-000000000001', '11111111-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000001', 'silent-patient-review', 'รีวิว The Silent Patient: แผนลวงคดีเงียบ', 'จิตวิทยาบำบัดสุดระทึก บทสรุปที่ตลบหลังคนอ่านอย่างเลือดเย็น', 'มีเพียงคนเดียวที่รู้ว่าเกิดอะไรขึ้นในคืนนั้น... และเธอปฏิเสธที่จะเอ่ยปากแม้แต่คำเดียว', ARRAY['จิตบำบัด', 'ผู้เล่าที่ไว้ใจไม่ได้', 'หักมุม'], 5.0, 'published', now()),
  ('22222222-0000-0000-0000-000000000002', '11111111-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000001', 'suspect-x-review', 'รีวิว กลลวงซ่อนตาย', 'การดวลตรรกะอันบริสุทธิ์เพื่อปกป้องคนที่ตนรัก', 'การตั้งโจทย์ที่ยากกับการแก้โจทย์ที่ยาก... อย่างไหนยากกว่ากัน?', ARRAY['แผนลวงสมบูรณ์แบบ', 'ตรรกะคณิตศาสตร์'], 5.0, 'published', now()),
  ('22222222-0000-0000-0000-000000000003', '11111111-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000001', 'gone-girl-review', 'รีวิว Gone Girl', 'สงครามประสาทของคู่สมรสที่ไม่มีใครยอมใคร', 'ไม่มีสิ่งใดหลอนเท่ากับการนอนข้างคนที่คุณไม่แน่ใจว่าเขารักคุณ... หรือกำลังวางแผนฆ่าคุณ', ARRAY['สงครามสมรส', 'Gaslighting'], 4.5, 'published', now()),

  ('22222222-0000-0000-0000-000000000004', '11111111-0000-0000-0000-000000000004', '00000000-0000-0000-0000-000000000001', '1984-review', 'รีวิว 1984 หนึ่ง-เก้า-แปด-สี่', 'วรรณกรรมดิสโทเปียที่ไม่มีวันล้าสมัยและเตือนสติมนุษยชาติ', 'สงครามคือสันติภาพ เสรีภาพคือการยอมจำนน อวิชชาคือพลัง', ARRAY['ดิสโทเปีย', 'ปรัชญาการเมือง'], 5.0, 'published', now()),
  ('22222222-0000-0000-0000-000000000005', '11111111-0000-0000-0000-000000000005', '00000000-0000-0000-0000-000000000001', 'little-prince-review', 'รีวิว เจ้าชายน้อย', 'บทเรียนความรักและความหมายของการผูกพัน', 'สิ่งสำคัญไม่อาจเห็นได้ด้วยดวงตา หากแต่ต้องมองด้วยหัวใจเท่านั้น', ARRAY['วรรณกรรมอมตะ', 'ความหมายชีวิต'], 5.0, 'published', now()),

  ('22222222-0000-0000-0000-000000000006', '11111111-0000-0000-0000-000000000006', '00000000-0000-0000-0000-000000000001', 'joy-of-life-review', 'รีวิว หาญท้าชะตาฟ้า ปริศนายุทธจักร', 'มหากาพย์การชิงไหวชิงพริบแห่งยุคสมัย', 'ชีวิตนี้ข้าไม่อยากเป็นหมากของสวรรค์ หากใต้หล้าไม่มีเส้นทาง ข้าจะฟันเบิกทางเอง', ARRAY['ชิงไหวพริบ', 'ราชสำนัก', 'วิทยายุทธ์'], 5.0, 'published', now()),
  ('22222222-0000-0000-0000-000000000007', '11111111-0000-0000-0000-000000000007', '00000000-0000-0000-0000-000000000001', 'condor-heroes-review', 'รีวิว มังกรหยก', 'ยอดวิชาและความกตัญญูของวีรบุรุษเพื่อแผ่นดิน', 'วีรบุรุษผู้ยิ่งใหญ่ ย่อมทำเพื่อบ้านเมืองและราษฎร', ARRAY['ยุทธภพคลาสสิก', 'วิทยายุทธ์'], 5.0, 'published', now()),

  ('22222222-0000-0000-0000-000000000008', '11111111-0000-0000-0000-000000000008', '00000000-0000-0000-0000-000000000001', 'behind-the-painting-review', 'รีวิว ข้างหลังภาพ', 'โศกนาฏกรรมแห่งความรักที่งดงามและตราตรึง', 'ฉันตายโดยปราศจากคนที่รักฉัน แต่ฉันก็อิ่มใจว่าฉันมีคนที่ฉันรัก', ARRAY['รักคลาสสิก', 'ความทรงจำ'], 5.0, 'published', now()),
  ('22222222-0000-0000-0000-000000000009', '11111111-0000-0000-0000-000000000009', '00000000-0000-0000-0000-000000000001', 'coffee-cold-review', 'รีวิว เพียงชั่วเวลากาแฟยังอุ่น', 'ความอบอุ่นและการยอมรับความจริงในอดีต', 'แม้ความจริงในอดีตจะไม่เปลี่ยน แต่หัวใจของคนที่กลับมา... จะเปลี่ยนไปตลอดกาล', ARRAY['เยียวยาใจ', 'อบอุ่น'], 5.0, 'published', now()),

  ('22222222-0000-0000-0000-000000000010', '11111111-0000-0000-0000-000000000010', '00000000-0000-0000-0000-000000000001', '20th-century-boys-review', 'รีวิว 20th Century Boys', 'มังงะสืบสวนไซไฟที่ยิ่งใหญ่ที่สุดเรื่องหนึ่งในประวัติศาสตร์', 'สัญลักษณ์นี้พวกเราเป็นคนวาดมันขึ้นมาเองในวันนั้น...', ARRAY['สืบสวน', 'ไซไฟ', 'มิตรภาพ'], 5.0, 'published', now()),
  ('22222222-0000-0000-0000-000000000011', '11111111-0000-0000-0000-000000000011', '00000000-0000-0000-0000-000000000001', 'monster-review', 'รีวิว Monster คนปีศาจ', 'การเดินทางเพื่อดับลมหายใจปีศาจที่ตนเคยช่วยชีวิตไว้', 'สำหรับมนุษย์เรา สิ่งเดียวที่เท่าเทียมกันอย่างแท้จริงก็คือความตาย', ARRAY['จิตวิทยา', 'อาชญากรรม'], 5.0, 'published', now());

