-- 6. เพิ่มบทความบล็อก (Blog Posts)
INSERT INTO public.blog_posts (slug, author_id, category, title, excerpt, quote, art_key, status, published_at, sections) VALUES
  ('slow-morning', '00000000-0000-0000-0000-000000000001', 'ชีวิตประจำวัน', 'เช้าวันที่ไม่ต้องรีบ', 'บางวันความสุขอาจเริ่มจากการตื่นช้าลงนิดหนึ่ง ชงเครื่องดื่มแก้วโปรด แล้วปล่อยให้เช้าเป็นของเรา', 'เราไม่จำเป็นต้องเริ่มทุกวันด้วยการวิ่ง บางเช้าการเดินช้า ๆ ก็พาเราไปไกลพอแล้ว', 'morning', 'published', now(),
   '[{"heading": "เริ่มวันโดยไม่เร่งตัวเอง", "paragraphs": ["เราเคยคิดว่าตอนเช้าต้องมีตารางที่แน่นอน แต่เช้าที่ช้าลงทำให้เราได้ยินเสียงความคิดตัวเองชัดขึ้น"]}, {"heading": "พื้นที่เล็ก ๆ สำหรับสิ่งที่ชอบ", "paragraphs": ["ลองเลือกกิจกรรมหนึ่งอย่างที่ไม่ต้องทำเพื่อใครเพื่ออยู่กับตัวเอง"]}]'::jsonb),
  ('small-corner', '00000000-0000-0000-0000-000000000001', 'บ้านและไอเดีย', 'มุมเล็ก ๆ ที่ทำให้บ้านน่าอยู่ขึ้น', 'ไม่ต้องเปลี่ยนบ้านทั้งหลัง แค่จัดแสง เก็บของที่ไม่ใช้ และเว้นที่ให้สิ่งที่ทำให้ยิ้มได้', 'บ้านที่ดีอาจไม่ใช่บ้านที่สมบูรณ์แบบ แต่เป็นบ้านที่เราพักได้จริง', 'home', 'published', now(),
   '[{"heading": "เริ่มจากมุมที่ใช้ทุกวัน", "paragraphs": ["เลือกมุมที่เราอยู่บ่อยที่สุดก่อน แล้วค่อยวางของที่ใช้งานจริงกลับไปทีละชิ้น"]}]'::jsonb),
  ('little-notes', '00000000-0000-0000-0000-000000000001', 'บันทึก', 'จดเรื่องเล็ก ๆ ที่อยากจำ', 'บันทึกไม่จำเป็นต้องสวยหรือยาว แค่หนึ่งประโยคจากวันนี้ก็อาจกลายเป็นความทรงจำที่มีค่า', 'บางเรื่องธรรมดาในวันนี้ คือเรื่องที่เราอยากกลับมาอ่านในอีกหลายปีข้างหน้า', 'notes', 'published', now(),
